-- A despejar estrutura da base de dados para flyaway_vam
CREATE DATABASE IF NOT EXISTS `flyaway_vam` /*!40100 DEFAULT CHARACTER SET utf8mb4 COLLATE utf8mb4_uca1400_ai_ci */;
USE `flyaway_vam`;

-- A despejar estrutura para tabela flyaway_vam.airports
CREATE TABLE IF NOT EXISTS `airports` (
  `id` bigint(20) unsigned NOT NULL AUTO_INCREMENT,
  `icao` varchar(4) NOT NULL,
  `name` varchar(255) NOT NULL,
  `city` varchar(255) NOT NULL,
  `country` varchar(255) NOT NULL,
  `lat` decimal(10,6) NOT NULL,
  `lng` decimal(10,6) NOT NULL,
  `elevation` int(11) DEFAULT NULL,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `icao` (`icao`)
) ENGINE=InnoDB AUTO_INCREMENT=7696 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

